create or replace function public.business_review_detail(p_business_id uuid,p_start timestamptz default (now()-interval '30 days'),p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) and not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role='analyst') and not exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin=true) then raise exception 'Not authorized for this business'; end if; return (select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select r.id,l.name location,r.stars,r.cleanliness_pct,r.comment,r.status,r.business_reply,r.created_at from public.reviews r join public.locations l on l.id=r.location_id where l.business_id=p_business_id and r.created_at between p_start and p_end and r.status='published') x); end; $function$;
comment on function public.business_review_detail(uuid,timestamptz,timestamptz) is 'Business review detail returns published reviews only; hidden/moderated reviews remain available to dedicated moderation/admin workflows and historical provenance.';
